using System.Linq;using System.Text;using UnityEditor;using UnityEngine;
public static class AgentBoneDump{public static string Run(){var sb=new StringBuilder();var path=System.IO.File.ReadAllText(System.IO.Path.Combine(Application.dataPath,"../AgentScripts/_bridge/arg.txt")).Trim();var root=PrefabUtility.LoadPrefabContents(path);foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("B-")))sb.AppendLine(t.name+" "+t.position.ToString("F3")+" rot "+t.rotation.eulerAngles.ToString("F0")+" ls "+t.lossyScale.x.ToString("F2"));var a=root.GetComponent<Animator>();sb.AppendLine("avatar "+(a&&a.avatar?a.avatar.name+" human="+a.avatar.isHuman:"none"));var s=root.GetComponentInChildren<SkinnedMeshRenderer>();sb.AppendLine("skin bones "+s.bones.Length+" root "+(s.rootBone?s.rootBone.name:"-")+" mesh "+s.sharedMesh.name+" v="+s.sharedMesh.vertexCount+" bounds "+s.sharedMesh.bounds);PrefabUtility.UnloadPrefabContents(root);return sb.ToString();}}
